import random
import math

def aperiodic_autocorr(seq):
    n = len(seq)
    C = []
    for k in range(1, n):
        ck = sum(seq[i] * seq[i+k] for i in range(n-k))
        C.append(ck)
    return C

def sum_sq_autocorr(seq):
    C = aperiodic_autocorr(seq)
    return sum(c*c for c in C)

# Try Legendre sequence for length 31
# Legendre symbol: (i/p) for i=0..p-1, with (0/p)=0, but we need +/-1
# For p=31 (prime), quadratic residues mod 31
p = 31
legendre = []
for i in range(p):
    if i == 0:
        legendre.append(1)  # or -1? Let's try both
    else:
        # check if i is quadratic residue mod p
        is_qr = False
        for j in range(1, p):
            if (j*j) % p == i:
                is_qr = True
                break
        legendre.append(1 if is_qr else -1)

print("Legendre seq:", legendre)
print("Sum sq autocorr:", sum_sq_autocorr(legendre))

